#include <stdio.h>
#include <limits.h>

#define CAP 32768
#define EMPTY ULLONG_MAX

unsigned long long exactSet[CAP];
unsigned long long prefixSet[10][CAP];
unsigned long long suffixSet[10][CAP];

static inline unsigned int hash_ull(unsigned long long x) {
    x ^= x >> 33;
    x *= 0xff51afd7ed558ccdULL;
    x ^= x >> 33;
    x *= 0xc4ceb9fe1a85ec53ULL;
    x ^= x >> 33;
    return (unsigned int)x;
}

int contains(unsigned long long *set, unsigned long long key) {
    unsigned int h = hash_ull(key) & (CAP - 1);
    while (set[h] != EMPTY) {
        if (set[h] == key) return 1;
        h = (h + 1) & (CAP - 1);
    }
    return 0;
}

void insert(unsigned long long *set, unsigned long long key) {
    unsigned int h = hash_ull(key) & (CAP - 1);
    while (set[h] != EMPTY) {
        if (set[h] == key) return;
        h = (h + 1) & (CAP - 1);
    }
    set[h] = key;
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    for (int i = 0; i < CAP; i++) {
        exactSet[i] = EMPTY;
    }
    for (int L = 0; L < 10; L++) {
        for (int i = 0; i < CAP; i++) {
            prefixSet[L][i] = EMPTY;
            suffixSet[L][i] = EMPTY;
        }
    }

    char s[11];
    for (int k = 1; k <= N; k++) {
        scanf("%s", s);

        unsigned long long pref[11], suff[11];
        pref[0] = 0;
        for (int L = 1; L <= 10; L++) {
            pref[L] = pref[L - 1] * 26 + (unsigned long long)(s[L - 1] - 'a');
        }
        for (int L = 1; L <= 10; L++) {
            unsigned long long code = 0;
            for (int j = 10 - L; j < 10; j++) {
                code = code * 26 + (unsigned long long)(s[j] - 'a');
            }
            suff[L] = code;
        }

        if (k > 1) {
            if (contains(exactSet, pref[10])) {
                printf("%s\n", s);
                return 0;
            }
            for (int t = 1; t <= 9; t++) {
                int L1 = 10 - t;
                int L2 = t;
                if (contains(suffixSet[L1], pref[L1]) &&
                    contains(prefixSet[L2], suff[L2])) {
                    printf("%s\n", s);
                    return 0;
                }
            }
        }

        insert(exactSet, pref[10]);
        for (int L = 1; L <= 9; L++) {
            insert(prefixSet[L], pref[L]);
            insert(suffixSet[L], suff[L]);
        }
    }

    printf("ok\n");
    return 0;
}
